using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using LWS.TruckSports.Editor;
namespace LWS.TruckFieldGoal.Editor {
public static class FieldGoalModels {
 const string Folder="TruckFieldGoal";
 public static Mesh Persist(string name,Vector3[] vertices,int[] triangles,Vector2[] uv=null){string path="Assets/"+Folder+"/Models/"+name+".asset";var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(mesh==null){mesh=new Mesh{name=name};AssetDatabase.CreateAsset(mesh,path);}mesh.Clear();mesh.vertices=vertices;mesh.triangles=triangles;mesh.uv=uv??vertices.Select(p=>new Vector2(p.z,p.y)).ToArray();mesh.RecalculateNormals();mesh.RecalculateBounds();mesh.UploadMeshData(false);EditorUtility.SetDirty(mesh);return mesh;}
 public static GameObject Part(Transform parent,string name,Mesh mesh,Material material){var g=new GameObject(name);g.transform.SetParent(parent,false);g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterial=material;return g;}
 public static Mesh Ball(string name,float low=-1.570796f,float high=1.570796f,float scale=1){const int rings=32,sides=64;var vertices=new List<Vector3>();var uv=new List<Vector2>();var triangles=new List<int>();for(int r=0;r<=rings;r++){float a=Mathf.Lerp(low,high,r/(float)rings);for(int n=0;n<=sides;n++){float t=n*Mathf.PI*2/sides;vertices.Add(new Vector3(Mathf.Cos(a)*Mathf.Cos(t)*.48f,Mathf.Cos(a)*Mathf.Sin(t)*.48f,Mathf.Sin(a)*.95f)*scale);uv.Add(new Vector2(n/(float)sides,r/(float)rings));if(r<rings&&n<sides){int i=r*(sides+1)+n,j=i+sides+1;triangles.AddRange(new[]{i,i+1,j,i+1,j+1,j});}}}return Persist(name,vertices.ToArray(),triangles.ToArray(),uv.ToArray());}
 public static GameObject Cylinder(Transform parent,string name,Vector3 a,Vector3 b,float radius,Material mat,bool physical=false){var g=GameObject.CreatePrimitive(PrimitiveType.Cylinder);g.name=name;g.transform.SetParent(parent,false);g.transform.localPosition=(a+b)*.5f;g.transform.localRotation=Quaternion.FromToRotation(Vector3.up,(b-a).normalized);g.transform.localScale=new Vector3(radius*2,Vector3.Distance(a,b)*.5f,radius*2);g.GetComponent<Renderer>().sharedMaterial=mat;if(!physical)UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());return g;}
 public static Mesh Boot(string name,bool sole){Vector2[] outline=sole?new[]{new Vector2(-1.45f,0),new Vector2(3.4f,0),new Vector2(3.8f,.3f),new Vector2(3.45f,.55f),new Vector2(-1.45f,.55f)}:new[]{new Vector2(-1.4f,.45f),new Vector2(3.4f,.45f),new Vector2(3.7f,.8f),new Vector2(3.3f,1.15f),new Vector2(1,1.4f),new Vector2(.1f,2.1f),new Vector2(-.05f,4.2f),new Vector2(-1.4f,4.2f)};var vertices=new List<Vector3>();var triangles=new List<int>();for(int side=0;side<2;side++)foreach(var p in outline)vertices.Add(new Vector3((side==0?-1:1)*(sole?1.5f:1.3f),p.y,p.x));int count=outline.Length;for(int i=1;i<count-1;i++)triangles.AddRange(new[]{0,i+1,i,count,count+i,count+i+1});for(int i=0;i<count;i++){int j=(i+1)%count;triangles.AddRange(new[]{i,j,i+count,j,j+count,i+count});}return Persist(name,vertices.ToArray(),triangles.ToArray());}
 public static void Football(Transform parent,Material leather,Material white){Part(parent,"Shaped American football",Ball("American football smooth shell"),leather);for(int side=-1;side<=1;side+=2){float a=side*.78f;Part(parent,"Curved white end stripe "+side,Ball("Surface mapped football end stripe "+side,a-.055f,a+.055f,1.004f),white);}Cylinder(parent,"Raised leather lace spine",new Vector3(0,.49f,-.33f),new Vector3(0,.49f,.33f),.023f,white);for(int i=0;i<7;i++){float z=(i-3)*.09f;float y=Mathf.Sqrt(Mathf.Max(0,1-z*z/(.95f*.95f)))*.48f+.016f;Cylinder(parent,"Crossed raised lace "+i,new Vector3(-.12f,y,z),new Vector3(.12f,y,z),.018f,white);}}
}
}
